// Products are actual VSIX installations. GUI actions use public controls;
// the fixed observer only reads public exports or probes an invalid PM token.
import fs from 'node:fs';
import path from 'node:path';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const hash=b=>createHash('sha256').update(b).digest('hex');
const canonical=value=>Array.isArray(value)?'['+value.map(canonical).join(',')+']':value!==null&&typeof value==='object'?'{'+Object.keys(value).filter(k=>value[k]!==undefined).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}':JSON.stringify(value)??'null';
function directoryDigest(root){const files=[];const walk=(dir,relative='')=>{for(const entry of fs.readdirSync(dir,{withFileTypes:true})){const file=path.join(dir,entry.name),name=path.join(relative,entry.name);if(entry.isDirectory())walk(file,name);else files.push([name,hash(fs.readFileSync(file))]);}};walk(root);return hash(canonical(files.sort((a,b)=>a[0].localeCompare(b[0]))));}
const sourceNames=['night4/spec/PM.md','night4/spec/CONTRACTS.md','night4/generated/PM-START.md','night4/spec/interfaces.ts','night4/spec/ux.csv','night4/spec/access.csv'];
function hosted(){if(process.env.GITHUB_ACTIONS!=='true'||process.env.RUNNER_OS!=='Windows')throw Error('Installed PM journey requires the isolated hosted Windows runner.');}
function git(root,...args){return execFileSync('git',['-c','core.hooksPath=NUL','-C',root,...args],{encoding:'utf8',windowsHide:true}).trim();}
export function preparePmAgentFixture(base,pmVsix,pmSha){
 hosted();if(!/^[a-f0-9]{40}$/.test(pmSha))throw Error('Exact PM source SHA required.');
 const receipt=JSON.parse(fs.readFileSync(path.join(path.dirname(path.resolve(pmVsix)),'receipt.json'),'utf8'));
 if(receipt.schema!=='datapass.installed-pm-fixture/1'||receipt.sourceSha!==pmSha||receipt.filename!==path.basename(pmVsix)||receipt.sha256!==hash(fs.readFileSync(pmVsix)))throw Error('PM VSIX differs from the exact-source installed fixture receipt.');
 const dependencyDir=path.dirname(path.resolve(pmVsix)),configDependency=JSON.parse(fs.readFileSync(path.join(dependencyDir,'config-dependency.json'),'utf8'));
 if(configDependency.schema!=='datapass.installed-companion-dependency/1'||configDependency.candidate!==false||configDependency.role!=='DEPENDENCY_ONLY'||configDependency.extensionId!=='julian-passebecq.datapass-native-config'||configDependency.filename!=='datapass-native-config-0.7.2.vsix'||configDependency.sha256!==hash(fs.readFileSync(path.join(dependencyDir,configDependency.filename))))throw Error('Unchanged Config dependency fixture differs from its fixed receipt.');
 const repository=path.join(base,'generated-project');fs.mkdirSync(repository,{recursive:true});
 git(repository,'init');git(repository,'config','user.name','Generated UI Fixture');git(repository,'config','user.email','fixture@example.invalid');
 fs.writeFileSync(path.join(repository,'README.md'),'# Generated PM Agent UI fixture\nOnly controlled qualification data.\n');fs.writeFileSync(path.join(repository,'.gitignore'),'.datapass/\n.native-config/\nexports/\n');
 git(repository,'add','README.md','.gitignore');git(repository,'commit','-m','Generated qualification baseline');git(repository,'remote','add','origin','https://github.com/julian-passebecq/datapass-pm.git');
 const featureIds=receipt.featureIds;if(!Array.isArray(featureIds)||featureIds.length!==107||new Set(featureIds).size!==107||featureIds.some(id=>typeof id!=='string'||! /^[A-Z]{2}-[0-9]{3}$/.test(id)))throw Error('Expected the reviewed 107 PM acceptance IDs.');
 const scope={projectId:'fixture-pm-agent',organizationId:'fixture-org',privacyDomainId:'fixture-private',repoId:'julian-passebecq/datapass-pm'};
 const registry={schema:'datapass.local-projects/1',projects:[{id:scope.projectId,name:'Generated PM Agent Project',organizationId:scope.organizationId,privacyDomainId:scope.privacyDomainId,repoIds:[scope.repoId],portfolios:[],categories:['fixture'],deployment:['local'],sourceNames,featureIds}],locations:[],grants:sourceNames.map(sourceName=>({sourceName,organizationId:scope.organizationId,privacyDomainId:scope.privacyDomainId}))};
 const registryFile=path.join(base,'generated-registry.json');fs.writeFileSync(registryFile,JSON.stringify(registry,null,2));fs.mkdirSync(path.join(repository,'exports'),{recursive:true});
 return {base,repository,registryFile,scope,featureIds,configDependency:{...configDependency,path:path.join(dependencyDir,configDependency.filename)},baselineRevision:git(repository,'rev-parse','HEAD'),taskFile:path.join(repository,'.datapass','tasks.json'),exportDir:path.join(repository,'exports'),pm:{sourceSha:pmSha,vsixSha256:receipt.sha256,version:receipt.version,provenance:receipt.provenance}};
}

export function installObserver(extDir,fixture){
 hosted();const directory=path.join(extDir,'fixture.pm-agent-observer-1.0.0');fs.mkdirSync(directory,{recursive:true});
 const output=path.join(fixture.base,'observer.json');fixture.observerFile=output;const draftDir=path.join(fixture.base,'..','pm-agent-drafts');
 fs.writeFileSync(path.join(directory,'package.json'),JSON.stringify({name:'pm-agent-observer',publisher:'fixture',version:'1.0.0',engines:{vscode:'^1.95.0'},main:'./extension.cjs',activationEvents:['onCommand:fixture.observePmAgent','onCommand:fixture.invalidPmReturn','onCommand:fixture.preserveDrafts'],contributes:{commands:[{command:'fixture.observePmAgent',title:'Fixture QA: Observe installed PM and Agent'},{command:'fixture.invalidPmReturn',title:'Fixture QA: Probe invalid PM return'},{command:'fixture.preserveDrafts',title:'Fixture QA: Preserve generated previews'}]}}));
 fs.writeFileSync(path.join(directory,'extension.cjs'),`const v=require('vscode'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');const output=${JSON.stringify(output)},project=${JSON.stringify(fixture.scope.projectId)},draftDir=${JSON.stringify(draftDir)},ownedBase=${JSON.stringify(fixture.base)};const owned=file=>[ownedBase,draftDir].some(root=>{const p=path.resolve(file).toLowerCase(),r=path.resolve(root).toLowerCase();return p===r||p.startsWith(r+path.sep);});
function save(update){let old={};try{old=JSON.parse(fs.readFileSync(output,'utf8'));}catch{}fs.writeFileSync(output,JSON.stringify({...old,...update},null,2));}
exports.activate=context=>{if(process.env.GITHUB_ACTIONS!=='true'||process.env.RUNNER_OS!=='Windows')throw Error('Hosted fixture only');context.subscriptions.push(v.commands.registerCommand('fixture.observePmAgent',async()=>{const a=v.extensions.getExtension('juliandatapass.agent-vscode'),p=v.extensions.getExtension('juliandatapass.datapass-pm');await a.activate();await p.activate();await p.exports.ready;const api=a.exports.cockpitV1;const reply=await api.getScopes(),scope=reply.data.find(s=>s.projectIds.includes(project));const mappings=scope?await api.getContextMappings({requestId:'fixture:observer',scope}):null;save({schema:'datapass.installed-public-api-observer/1',observedAt:Date.now(),host:{vscodeVersion:v.version,extensionHostPid:process.pid,installedExtensions:[{id:a.id,version:a.packageJSON.version},{id:p.id,version:p.packageJSON.version},...(v.extensions.getExtension('julian-passebecq.datapass-native-config')?[{id:'julian-passebecq.datapass-native-config',version:v.extensions.getExtension('julian-passebecq.datapass-native-config').packageJSON.version,role:'DEPENDENCY_ONLY',candidate:false}]:[])]},products:{agent:a.packageJSON.version,pm:p.packageJSON.version},pmState:p.exports.cockpit.getState(),pmDiagnostics:p.exports.diagnostics(),pmEvidence:(()=>{const view=p.exports.cockpit.getViewData();return {preparedPrompt:view.preparedPrompt??null,nativePreparedTask:view.nativePreparedTask??null,configBinding:view.configBinding??null,agentScope:view.agentScope??null,local:view.local??null};})(),scope:scope??null,mappings,authority:'READ_ONLY_PUBLIC_API',productTransportMocked:false});}),v.commands.registerCommand('fixture.invalidPmReturn',async()=>{let rejected=false,ack=null,reason=null;try{ack=await v.commands.executeCommand('datapassPm.returnFromAgent',{returnToken:'pm:invalid-fixture',requestId:'fixture:invalid',generation:'invalid',scopeHash:'0'.repeat(64),epoch:0});}catch(e){rejected=true;reason=String(e.message).slice(0,240);}save({invalidReturn:{rejected,ack:ack??null,reason,authority:'ACTUAL_PUBLIC_COMMAND'}});}),v.commands.registerCommand('fixture.preserveDrafts',()=>{fs.mkdirSync(draftDir,{recursive:true});const retained=[];for(const doc of v.workspace.textDocuments.filter(d=>d.uri.scheme==='untitled'||d.uri.scheme==='file'&&owned(d.uri.fsPath))){const text=doc.getText(),digest=crypto.createHash('sha256').update(text).digest('hex');fs.writeFileSync(path.join(draftDir,digest+'.txt'),text);retained.push({sha256:digest,bytes:Buffer.byteLength(text),generated:true,uri:doc.uri.toString(),label:doc.uri.scheme==='file'?path.basename(doc.uri.fsPath):doc.uri.path,isDirty:doc.isDirty,isUntitled:doc.isUntitled,role:'GENERATED_OWNED_PROFILE_PREVIEW'});}save({retainedGeneratedPreviews:retained,draftObservedAt:Date.now(),activePreview:v.window.activeTextEditor?{uri:v.window.activeTextEditor.document.uri.toString(),isDirty:v.window.activeTextEditor.document.isDirty,isUntitled:v.window.activeTextEditor.document.isUntitled}:null});}));};`);
 return output;
}

