   const frame=await nav('Campaigns');const edit=frame.locator('form[data-action="saveCampaign"] textarea[name="common"]');const prior=await edit.inputValue();await edit.fill('1gr/?');await edit.press('Control+Alt+1');action(`PM ${label} campaign typing keeps page and focus`,await edit.inputValue()==='1gr/?'&&await frame.locator('[data-action="navigate"][data-value="Campaigns"][aria-pressed="true"]').count()===1&&await edit.evaluate(el=>el===document.activeElement));await edit.fill(prior);await frame.locator('form[data-action="saveCampaign"] button[type="submit"]').click();await win.waitForTimeout(500);
